def get_data_from_file(file_path):
    file_io = FileIO(file_path)
    df = file_io.read(return_type='dataframe')
    return df
def convert_to_list(item):
    """
    将输入数据转换为list格式
    """
    if item == '' or item == []:
        return ({'error_no': -1, 'error_info': '输入格式有误'}, [])
    elif item and not isinstance(item, str) and not isinstance(item, list):
        return ({'error_no': -1, 'error_info': '输入格式有误'}, [])
    elif isinstance(item, str):
        item = item.strip().split(',')
        return ({'error_no': 0, 'error_info': ''}, item)
    else:
        return ({'error_no': 0, 'error_info': ''}, item)
def get_changed_params(params, start_year, end_year, report_types):
    """
    开始年份、截止年份及季度数据的转换接口
    """
    if report_types is not None:
        params['report_types'] = report_types
    else:
        params['report_types'] = '1,2,3,4'
    if start_year is None:
        if end_year is None:
            params['start_year'] = str(qdt.datetime.now().year - 1)
            params['end_year'] = qdt.datetime.now().year
        else:
            params['start_year'] = str(int(end_year) - 1)
            params['end_year'] = end_year
    elif end_year is None:
        params['start_year'] = start_year
        params['end_year'] = qdt.datetime.now().year
    else:
        params['start_year'] = start_year
        params['end_year'] = end_year
    return params
def date_to_quarter(date, report_types):
    """
    计算date对应前一季度的开始年份、结束年份及具体的季度
    """
    year = int(date[:4])
    quarter = pandas.Period(date, 'Q-DEC').quarter
    if report_types is None:
        if quarter == 1:
            quarter = 4
            year -= 1
        else:
            quarter -= 1
    elif quarter <= report_types:
        quarter = report_types
        year -= 1
    else:
        quarter = report_types
    return (str(year), str(year), str(quarter))
def get_fields(table, fields):
    """
    获取相应表的field字段,fields不为空直接返回，为空则先去请求一次获取默认字段
    """
    try:
        if fields is None:
            if table == 'valuation':
                financial_data_tmp = const.VALUATION_FIELDS
            else:
                financial_data_tmp = const.FIANACE_TABLE_FACTOR_INFO_ENUM[table]
            return financial_data_tmp
        else:
            return fields
    except BaseException as e:
        system_log.exception('异常信息:%s' % get_traceback_message())
        return e
def fill_missing_stock_data(security, data):
    """
    对年份类型返回的panel类型股票数据进行填充
    end_date取所有返回数据的最大的不同日期集合值
    :param security: 用户传入的股票代码列表
    :param data: 获取的所有股票的财务数据
    :return: 填充后的数据
    """
    secu_code_return = data['secu_code'].unique()
    end_date_return = data['end_date'].unique()
    secu_filled_list = list(set(security) - set(secu_code_return))
    data_list = list()
    warning_stock_list = list()
    for stock in secu_filled_list:
        for date in end_date_return:
            data_tmp = dict()
            data_tmp['secu_code'] = stock
            data_tmp['end_date'] = date
            data_list.append(data_tmp)
        warning_stock_list.append(stock)
    if len(warning_stock_list) > 0:
        system_log.warning('%s获取数据为空，请查看证券代码是否正确或联系管理员!' % warning_stock_list)
        user_log.warning('%s获取数据为空，请查看证券代码是否正确或联系管理员!' % warning_stock_list)
    data_filled = pandas.DataFrame(data_list, columns=data.columns)
    data = pandas.concat([data, data_filled])
    return data
def get_valid_date_fundamentals_func(date, now):
    if isinstance(date, str):
        if not isVaildDate(date):
            raise ValueError('get_fundamentals函数入参date格式不正确')
        date = get_fundamentals_qry_date(now, date=date)
    elif isinstance(date, qdt.date):
        date = get_fundamentals_qry_date(now, date=date)
    else:
        raise ValueError('get_fundamentals函数入参date格式不正确')
    return date_str_type_change(date, '%Y-%m-%d', '%Y%m%d')
def get_fundamentals_qry_date(now, date=None):
    return get_qry_date(now, date=date, date_type='pre')
def filter_nan_and_none(data):
    if numpy.isnan(data) or data is None:
        return True
    return False
